import{_ as t,o as a,c as l,aw as r}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"HTTP Headers","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/http/3-http-headers.md","filePath":"wiki/dev-commit/network/network/http/3-http-headers.md"}'),i={name:"wiki/dev-commit/network/network/http/3-http-headers.md"};function o(s,e,n,h,c,d){return a(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="http-headers" tabindex="-1">HTTP Headers <a class="header-anchor" href="#http-headers" aria-label="Permalink to &quot;HTTP Headers&quot;">​</a></h1><ul><li><p><strong>Заголовки HTTP</strong> - строки в HTTP-сообщении, содержащие разделённую двоеточием пару параметр-значение</p></li><li><ol><li>General Headers («Основные заголовки») - основные заголовки для запросов клиента и ответов сервера</li></ol></li><li><ol start="2"><li>Request Headers («Заголовки запроса») - используются только в запросах клиента</li></ol></li><li><ol start="3"><li>Response Headers («Заголовки ответа») - только для ответов от сервера</li></ol></li><li><ol start="4"><li>Entity Headers («Заголовки сущности») - заголовки, сопровождающие каждую сущность как в запросах клиента, так и в ответах сервера</li></ol></li></ul><h3 id="_1-general-headers" tabindex="-1">1. General Headers <a class="header-anchor" href="#_1-general-headers" aria-label="Permalink to &quot;1. General Headers&quot;">​</a></h3><ul><li>Request URL : <a href="https://api.project.com/api/user" target="_blank" rel="noreferrer">https://api.project.com/api/user</a></li><li>Request Method : POST</li><li>Status Code : 200 OK</li><li>Remote Address : 107.22.174.243:443</li><li>Referrer Policy : strict-origin-when-cross-origin Определяет, сколько информации о referrer (отправляемой с заголовком Referer) должно быть включено в запросы</li></ul><h3 id="_2-request-headers" tabindex="-1">2. Request Headers <a class="header-anchor" href="#_2-request-headers" aria-label="Permalink to &quot;2. Request Headers&quot;">​</a></h3><ul><li>Accept : text/plain Список допустимых форматов ресурса</li><li>Accept-Encoding : &lt;compress | gzip | deflate | sdch | identity&gt; Перечень поддерживаемых способов кодирования содержимого сущности при передаче</li><li>Accept-Language : ru,en Список поддерживаемых естественных языков</li><li>Authorization : Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ== Данные для авторизации</li><li>Connection : close | keep-alive Сведения о проведении соединения</li><li>Host : api.project.com Доменное имя и порт хоста запрашиваемого ресурса. Необходимо для поддержки виртуального хостинга на серверах</li><li>Origin : <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a></li><li>Referer : <a href="http://localhost:3000/" target="_blank" rel="noreferrer">http://localhost:3000/</a> Полный или относительный URI ресурса, с которого клиент сделал текущий запрос</li><li>User-Agent : Mozilla/5.0 (X11; Linux i686; rv:2.0.1) Gecko/20100101 Firefox/4.0.1 Список названий и версий клиента и его компонентов с комментариями</li></ul><h3 id="_3-response-headers" tabindex="-1">3. Response Headers <a class="header-anchor" href="#_3-response-headers" aria-label="Permalink to &quot;3. Response Headers&quot;">​</a></h3><ul><li>Allow : OPTIONS, GET, HEAD Список поддерживаемых методов</li><li>Cache-Control : no-cache ... Директивы для управления кэшированием</li><li>Connection : close | keep-alive Сведения о проведении соединения</li><li>Content-Length : 1348 Размер содержимого сущности в октетах (байтах)</li><li>Content-Type : text/html;charset=utf-8 Формат и способ представления сущности</li><li>Date : Tue, 15 Nov 1994 08:12:31 GMT Дата генерации отклика</li></ul><h3 id="_4-entity-headers" tabindex="-1">4. Entity Headers <a class="header-anchor" href="#_4-entity-headers" aria-label="Permalink to &quot;4. Entity Headers&quot;">​</a></h3><ul><li>Content-Language : en, ru Один или несколько естественных языков содержимого сущности</li></ul><h3 id="неизвестно" tabindex="-1">Неизвестно <a class="header-anchor" href="#неизвестно" aria-label="Permalink to &quot;Неизвестно&quot;">​</a></h3><ul><li>Accept-Charset : utf-8 Перечень поддерживаемых кодировок для предоставления пользователю</li><li>Expires : Tue, 31 Jan 2012 15:02:53 GMT Дата предполагаемого истечения срока актуальности сущности</li><li>Location : <a href="http://example.com/about" target="_blank" rel="noreferrer">http://example.com/about</a> URI по которому клиенту следует перейти или URI созданного ресурса</li><li>Proxy-Authorization : Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ== Информация для авторизации на прокси-сервере</li><li>Server : Apache/2.2.17 (Win32) PHP/5.3.5 Список названий и версий веб-сервера и его компонентов с комментариями</li><li>Title Заголовок сущности</li></ul>',12)])])}const _=t(i,[["render",o]]);export{u as __pageData,_ as default};
